import ToggleGroup from "@marko-ui/shadcn/ui/toggle-group/toggle-group.marko";

static const ALIGNMENT = [
  { value: "left", label: "Left" },
  { value: "center", label: "Center" },
  { value: "right", label: "Right" },
];

<ToggleGroup items=ALIGNMENT defaultValue=["center"]/>

import ToggleGroup from "@marko-ui/shadcn/ui/toggle-group/toggle-group.marko";

static const FORMATTING = [
  { value: "bold", label: "B" },
  { value: "italic", label: "I" },
  { value: "underline", label: "U", disabled: true },
];

<ToggleGroup items=FORMATTING multiple value=["bold"]/>

import ToggleGroup from "@marko-ui/shadcn/ui/toggle-group/toggle-group.marko";

static const ALIGNMENT = [
  { value: "left", label: "Left" },
  { value: "center", label: "Center" },
  { value: "right", label: "Right" },
];

<ToggleGroup items=ALIGNMENT variant="outline" value=["left"]/>

import ToggleGroup from "@marko-ui/shadcn/ui/toggle-group/toggle-group.marko";

static const SIDES = [
  { value: "top", label: "Top" },
  { value: "bottom", label: "Bottom" },
  { value: "left", label: "Left" },
  { value: "right", label: "Right" },
];

<ToggleGroup items=SIDES size="sm" variant="outline" spacing=2 value=["top"]/>

import ToggleGroup from "@marko-ui/shadcn/ui/toggle-group/toggle-group.marko";

static const ALIGNMENT = [
  { value: "left", label: "Left" },
  { value: "center", label: "Center" },
  { value: "right", label: "Right" },
];

<ToggleGroup items=ALIGNMENT value=["left"] disabled/>
